(45748, 'ruRU', 'Жемчужина глубин', 'Отнесите жемчужину глубин полководцу Горчуку в Силитус.', 'Поверхность жемчужины идеально гладкая, а сама она кажется удивительно тяжелой.', '', '', '', '', '', '', 29981),
(45744, 'ruRU', 'Падение Сквернскорна', '', '', '', '', '', '', '', '', 29981),
(45743, 'ruRU', 'Суд Одина', '', '', '', '', '', '', '', '', 29981),
(45079, 'ruRU', 'Деревня Гленбрук', 'Узнайте о судьбе жителей Гленбрука.', '<В этой книге перечислены все жители Гленбрука.$b$bПрактически все имена вычеркнуты; осталось лишь несколько.>', '', '', '', '', '', '', 29981),
(44785, 'ruRU', 'Чаепитие', 'Отыщите Эбби Льюис.', 'Прости... Прости меня. Я... Я не могу...$b$b\n<Вы слышите шаги у себя за спиной.>$b$b\nЭ... Эбби? Что...', '', '', '', '', '', '', 29981),
(44305, 'ruRU', 'РАЗЫСКИВАЕТСЯ: Бахагар', '', '', '', '', '', '', '', '', 29981),
(44158, 'ruRU', 'Охота на иссохших: Фаланаар', '', '', '', '', '', '', '', '', 29981),
