INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`, `AreaDescription`, `PortraitGiverText`, `PortraitGiverName`, `PortraitTurnInText`, `PortraitTurnInName`, `QuestCompletionLog`, `VerifiedBuild`) VALUES
(55668, 'ruRU', 'Награда за самоотверженность', '', '', '', '', '', '', '', '', 29981),
(55667, 'ruRU', 'Награда за самоотверженность', '', '', '', '', '', '', '', '', 29981),
(55635, 'ruRU', 'Голос на ветру', 'Найдите источник таинственного голоса в Друстваре.', '<Ваш разум заполняет таинственный шепот, звучащий как будто издалека.>\n\nМои чары не утеряны...\n\nНайди меня...\n\nДруствар...\n\nЛистопадная Бухта...', '', '', '', '', '', '', 29981),
(55596, 'ruRU', 'Все на своем месте', 'Вернитесь к Сешули в Дазар\'алор и расскажите о своем открытии.', '<Сешули будет интересно узнать, как вы восстановили этот алтерь.$b$bОсобенно ей понравится та часть, где вам пришлось пробиваться Атал\'Дазар.>', '', '', '', '', '', '', 29981),
(55594, 'ruRU', 'Последняя шлифовка', 'Вернитесь к Сешули в Дазар\'алор и расскажите о своем открытии.', '<Сешули будет интересно узнать о ваших успехах в восстановлении алтаря.$b$bВы чувствуете необходимость рассказать ей обо всем как можно скорее.>', '', '', '', '', '', '', 29981),
(55592, 'ruRU', 'Многообещающее начало', 'Вернитесь к Сешули в Дазар\'алор и расскажите о своем открытии.', '<Алтарь восстановлен, и теперь вам не терпится найти следующий.$b$bВозможно, Сешули подскажет, где его искать.>', '', '', '', '', '', '', 29981),
(55590, 'ruRU', 'Все на своем месте', 'Вернитесь к Сэмюэлу Д. Колтону III в Боралус и расскажите о своем открытии.', '<Сэмюэлу будет интересно узнать, как вы восстановили этот алтарь.$b$bОсобенно ему понравится та часть, где вам пришлось пробиваться через тюрьму.>', '', '', '', '', '', '', 29981),
(55586, 'ruRU', 'Все отшлифовано', 'Вернитесь к Сэмюэлу Д. Колтону III в Боралус и расскажите о своем открытии.', '<Сэмюэлу будет интересно узнать о ваших успехах в восстановлении алтаря.$b$bВы чувствуете необходимость рассказать ему обо всем как можно скорее.>', '', '', '', '', '', '', 29981),
(55585, 'ruRU', 'Многообещающее начало', 'Вернитесь к Сэмюэлу Д. Колтону III в Боралус и расскажите о своем открытии.', '<Алтарь восстановлен, и теперь вам не терпится найти следующий.$b$bВозможно, Сэмюэл подскажет, где его искать.>', '', '', '', '', '', '', 29981),
(55583, 'ruRU', 'Долой старый хлам', 'Ограните $1oa |4рубеллит:рубеллита:рубеллитов; проницательности и замените ими старые камни.', '<Осмотрев алтарь, вы заметили кое-что... знакомое. То, как огранены здешние камни, напоминает примитивную или упрощенную версию огранки рубеллитов, которой вас обучили.$b$bОчевидно, что время сильно изменило самоцветы: какие-то истерлись, какие-то растрескались. $b$bСкорее всего, алтарь можно будет восстановить, если заменить старые самоцветы новыми камнями того же вида и огранки.>', '', '', '', '', '', '', 29981),
(55582, 'ruRU', 'Атал\'Дазар: не все, что блестит...', 'Отправляйтесь в Атал\'Дазар и найдите замену треснувшему самоцвету.', '<Вы осматриваете алтарь и понимаете, что его центральный самоцвет покрыт глубокими трещинами и нуждается в замене.$b$bВы обращаетесь к записям и узнаете, что эти камни были принесены из \"золотого святилища\".$b$bС учетом вашего местонахождения, этим святилищем мог быть только Атал\'Дазар. Возможно, вам удастся найти замену в этом древнем городе.>', '', '', '', '', '', '', 29981),
(55581, 'ruRU', 'Дюны в лучах солнца', 'Следуйте за пометкой на карте в место, где должны быть самоцветы, и соберите $1oa. После этого отполируйте их и придайте форму.', '<Обходя алтарь, вы понимаете, что песчаные бури оказали на самоцветы разрушительное действие: в некоторых зияют трещины, другие приняли странную форму.$b$bВ своих записях земельник упоминал о том, что ему довелось пересекать дюны, усыпанные оранжевыми камнями. Они напоминали ему местный мягкий свет.$b$bСогласно записям, эти самоцветы можно найти к югу от вашего местоположения.>', '', '', '', '', '', '', 29981),
(55580, 'ruRU', 'Горные разработки', 'Обыщите Гол Озигр и узнайте, какие самоцветы использовались для постройки алтаря.', '<Изучая алтарь, вы заметили, что некоторые из вставленных в него камней потрескались. Их нужно заменить.$b$bИз своих заметок вы узнаете, что земельник добывал самоцветы, уничтожая элементалей земли к югу от алтаря.$b$bВы смотрите на карту и вам кажется, что речь шла о тех самых руинах древнего поселения, населенных враждебными созданиями и нежитью.$b$bМожет, там у вы отыщете подсказки к поиску самоцветов.>', '', '', '', '', '', '', 29981),
(55579, 'ruRU', 'Копнуть поглубже', 'Отправляйтесь к Холмам Поющих Ветров и соберите $1oa |4осколок:осколка:осколков; золотистого берилла.', '<Изучив алтарь, вы обнаруживаете, что в некоторых местах самоцветы отсутствуют.$b$bКроме того, центральный камень алтаря потрескался.$b$bВы сверяетесь с записями: земельник упоминал о том, что самоцветы можно получить путем просеивания руды из горы, расположенной к северу отсюда.$b$bЕсли просеять породу из этой области, то, возможно, вам удастся найти больше таких камней.>', '', '', '', '', '', '', 29981),
(55578, 'ruRU', 'Тол Дагор: самоцвет приливов', 'Поговорите со \"Скользким\" Солтоном и расспросите о пропавшем центральном элементе рисунка.', '<Вы смотрите на алтарь перед вами и поражаетесь его великолепию.$b$bЕго поверхность безупречно инкрустирована лазурными камнями, которые образуют звезду с лучами, сходящимися в центре.$b$bИ центр этот зияет пустотой. Вам кажется, что это ненормально. Вы быстро осматриваетесь в поисках того, что можно поместить в центр звезды, но ничего не находите.$b$bИ вдруг вы замечаете рядом пьяного незнакомца. Возможно, он что-то знает о судьбе пропавшей части алтаря.>', '', '', '', '', '', '', 29981),
(55516, 'ruRU', 'Искра гениальности', 'Встретьтесь с Мимироном в Библиотеке Изобретателя на Грозовой гряде.', '$n! Мне нужна твоя помощь.\n\nПосле инцидента с Саргерасом я установил несколько датчиков, и недавно они засекли всплеск энергии.\n\nСогласно первичному анализу, его источником был Хати, легендарное порождение магии молний. Несколько лет назад он был привязан к Мощи Титанов – артефакту, что помог нам одолеть Легион!\n\nДух Хати по-прежнему связан с сущностью артефакта. А это значит, что мне понадобится твоя помощь. Немедленно отправляйся в мою библиотеку на Грозовой гряде!', '', '', '', '', '', 'Встретьтесь с Мимироном в Библиотеке Изобретателя на Грозовой гряде.', 29981),
(55511, 'ruRU', 'Убить их всех!', 'Убейте 10 воинов Альянса по приказу командира Дардоша с озера Ледяных Оков.', 'Добро пожаловать в крепость Ледяных Оков, $n. Вождь Гаррош требует лишь одного: всех убить!$B$BВозвращайся ко мне, когда десять отборных бойцов Альянса будут мертвы.', '', '', '', '', '', '', 29981),
(55510, 'ruRU', 'Беспощадным пощады не будет', 'Убейте 10 воинов Орды по приказу командира Заннета из крепости Ледяных Оков.', 'Добро пожаловать в крепость Ледяных Оков, $n. Твое задание будет очень простым. Одержи победу над десятью отборными представителями Орды. А теперь ступай! Принеси победу Альянсу!', '', '', '', '', '', '', 29981),
(55509, 'ruRU', 'Победа на озере Ледяных Оков', 'Выиграйте битву на поле боя озера Ледяных Оков и вернитесь к офицеру-стратегу Килрату в крепость Ледяных Оков в Нордсколе. Необходимо принять участие в битве, чтобы выиграть ее.', 'Хотя Дардош весьма успешно справляется с уничтожением наших врагов, более важным для нас является контроль над крепостью Ледяных Оков. Сделай все, что потребуется, чтобы она принадлежала нам.$B$BНе думай, что союзники сделают за тебя всю грязную работу. Если к концу битвы не станешь рекрутом хотя бы второго уровня, можешь не возвращаться.', 'Победа на озере Ледяных Оков', '', '', '', '', 'Вернитесь к офицеру-стратегу Килрату на озеро Ледяных Оков.', 29981),
(55508, 'ruRU', 'Победа на озере Ледяных Оков', 'Выиграйте битву на озере Ледяных Оков и вернитесь к офицеру-стратегу Абрамису в крепость Ледяных Оков в Нордсколе. Необходимо принять участие в битве, чтобы выиграть ее.', 'Командир Заннет, должно быть, очень доволен видом груды ордынских тел у его ног, но контроль над озером Ледяных Оков – приоритетная задача экспедиции Отважных. Сделай все возможное, чтобы эта территория оставалась нашей.$B$BНе думай, что союзники сделают за тебя всю грязную работу. Если к концу битвы не станешь рекрутом хотя бы второго уровня, можешь не возвращаться.', 'Победа на озере Ледяных Оков', '', '', '', '', 'Вернитесь к офицеру-стратегу Абрамису на озеро Ледяных Оков.', 29981),
(55499, 'ruRU', 'Мерцающий кристалл', 'Отнесите искаженный временем мерцающий кристалл Кроннусу в Копье Войны.', 'На вид кристалл кажется вам знакомым, но, коснувшись его пальцем, вы понимаете, что это не просто камень. Перед вашим взором возникает картина утраченной великой цивилизации. Куда бы ни пал ваш взгляд, вы видите блеск золота, а сверху время от времени падают яркие пурпурные перья. Вдали вы слышите звуки битвы, которые обрываются чудовищным взрывом. Все ваши чувства бунтуют, а мир вокруг становится белым.\n\nКогда вы приходите в себя, в вас пробуждается необъяснимая тяга оказаться в Ашране.', '', '', '', '', '', '', 29981),
(55498, 'ruRU', 'Мерцающий кристалл', 'Отнесите искаженный временем мерцающий кристалл Темпре в Преграду Ветров.', 'На вид кристалл кажется вам знакомым, но, коснувшись его пальцем, вы понимаете, что это не просто камень. Перед вашим взором возникает картина утраченной великой цивилизации. Куда бы ни пал ваш взгляд, вы видите блеск золота, а сверху время от времени падают яркие пурпурные перья. Вдали вы слышите звуки битвы, которые обрываются чудовищным взрывом. Все ваши чувства бунтуют, а мир вокруг становится белым.\n\nКогда вы приходите в себя, в вас пробуждается необъяснимая тяга оказаться в Ашране.', '', '', '', '', '', '', 29981),
