UPDATE `quest_template_locale` SET `QuestDescription`='Экзарх должен быть столпом силы, и нет силы большей, нежели мужество встретить опасность.$B$BДалеко к северо-западу, среди заснеженных утесов хребта Ледяного Огня, живет изначальный Гнев по имени Вечногорящий.$B$BЛишь столкнувшись с одним из этих созданий лицом к лицу, познаешь ты пределы своей смелости.', `VerifiedBuild`=29981 WHERE (`ID`=36164 AND `locale`='ruRU');
UPDATE `quest_template_locale` SET `LogDescription`='Вернитесь к Мак\'джину с заметками рыбаков из клана Северного Волка.', `QuestDescription`='Что ж, ты $gпоказал:показала;, на что $gспособен:способна;. На, возьми эти заметки рыбаков из клана Северного Волка, возвращайся в свой гарнизон и изучай на здоровье. Если осилишь, потом хоть кракена выловить сможешь.', `VerifiedBuild`=29981 WHERE (`ID`=36132 AND `locale`='ruRU');
