UPDATE `quest_template_locale` SET `QuestDescription`='Поначалу клан Скользкой Чешуи опасался подходить к диким змеям.$B$BНо потом я застукал их, когда они под покровом ночи крали яйца.$B$BТеперь они уже вовсю уничтожают взрослых и молодняк!$B$BЕсли мы будем бездействовать, эти нежные создания исчезнут без следа, и орден Облачного Змея прекратит свое существование!$B$BУничтожь этих гнусных браконьеров из клана Скользящего Плавника, и тогда мы поговорим.', `VerifiedBuild`=29981 WHERE (`ID`=30135 AND `locale`='ruRU');
