UPDATE `quest_template_locale` SET `QuestDescription`='Порой я тоскую по тем дням, когда легионы могучих огров шли в бой плечом к плечу с воинами Орды – и Альянс содрогался перед их яростью. Возможно, эти славные времена вернутся прежде, чем я уйду к предкам.$B$BНо сейчас не об этом. Огр-маг Глубток присоединился к братству Справедливости и служит штейгером у них в шахте. Жалкий кретин! Покончи с ним ради меня, а главное – ради чести и славы Орды!', `VerifiedBuild`=29981 WHERE (`ID`=27842 AND `locale`='ruRU');
