UPDATE `quest_template_locale` SET `QuestDescription`='<ПУО жужжит.>$B$BГоворит командор Лорна Краули из фронта освобождения Гилнеаса! Если вы слышите это сообщение, то знаете – Альянс вновь контролирует Гилнеас. Сложите оружие и сдавайтесь. Неподчинение приказу карается смертью.$B$BВаши позиции обнаружены, скоро туда прибудут наши силы. Сопротивление бесполезно.', `PortraitGiverName`='Командор Лорна Краули', `VerifiedBuild`=29981 WHERE (`ID`=27423 AND `locale`='ruRU');
