UPDATE `quest_template_locale` SET `QuestDescription`='Деревню Каменного Молота захватил выводок Ониксии. Но зачем дочь великого дракона Смертокрыла вторглась в наши земли? Вот что тревожнее всего.$B$BНеужели только ради уничтожения небольшого поселения огров?$B$BПредупреди Мок\'Морокка. Нельзя сидеть сложа руки!', `VerifiedBuild`=29981 WHERE (`ID`=27416 AND `locale`='ruRU');
