UPDATE `quest_template_locale` SET `QuestDescription`='Отличное развлечение, но не стоит забывать, что мы здесь ради Гномрегана!$b$bМы обнаружили капитана братства Южных Морей на одном из кораблей на юге, прямо за той территорией, где разворачивались основные боевые действия. На своем корабле он один и совершенно беззащитен!$b$bЕсли ты позаботишься о нем, остальные пираты мигом притихнут.', `VerifiedBuild`=29981 WHERE (`ID`=25166 AND `locale`='ruRU');
