UPDATE `quest_template_locale` SET `QuestDescription`='С незапамятных времен мы воюем с ограми Камнерогов.$B$BНам удалось оттеснить их так, что теперь они едва держатся на заставе Камнерогов. Это назад по той дороге, который ты $Gпришел:пришла;, на юго-западной заставе Камнерогов.$B$BПокажи себя, убив их вождя, Гноша Брогната.$B$BПосмотрим по твоим делам с ограми, из какого теста ты $Gслеплен:слеплена;.', `VerifiedBuild`=29981 WHERE (`ID`=10843 AND `locale`='ruRU');
