UPDATE `quest_template_locale` SET `QuestDescription`='Я всегда держу свое слово, $n. Тебе поистине удалось произвести на меня впечатление.$B$BЯ намереваюсь дать тебе кристалл Ата\'мала для передачи наару. Я прошу тебя доставить его им – твой героизм делает это вполне возможным.$B$BМожешь использовать мой личный телепорт, чтобы переправиться прямо в город Шаттрат. Просто пройди через него, и окажешься там.$B$BОтдай кристалл наару по имени А\'дал, обитающему на Террасе Света. Пусть несут тебя попутные ветра торговли!', `VerifiedBuild`=29981 WHERE (`ID`=10280 AND `locale`='ruRU');
